#include <stdio.h>
#include <string.h>

/* Returns 1 if str is generated by S -> 0A1, A -> 0A | 1A | epsilon */
int belongs(const char *str) {
    int len = (int)strlen(str);

    /* S -> 0 A 1 needs at least the two terminals 0 and 1 */
    if (len < 2) return 0;

    /* Only the terminals 0 and 1 exist in this grammar */
    for (int i = 0; i < len; i++)
        if (str[i] != '0' && str[i] != '1') return 0;

    if (str[0] != '0')       return 0;   /* S must begin with 0 */
    if (str[len - 1] != '1') return 0;   /* S must end with 1   */

    /* Everything in between is generated by A -> 0A | 1A | epsilon */
    return 1;
}

/* Prints the leftmost derivation of an accepted string */
void print_derivation(const char *str) {
    int len = (int)strlen(str);
    int mid = len - 2;                   /* symbols generated by A */

    printf("\nDerivation:\n");
    printf("S => 0A1            (S -> 0A1)\n");

    for (int i = 1; i <= mid; i++) {
        printf("  => 0");
        for (int j = 1; j <= i; j++) printf("%c", str[j]);
        printf("A1");
        printf("          (A -> %cA)\n", str[i]);
    }

    printf("  => %s", str);
    printf("          (A -> epsilon)\n");
}

int main(void) {
    char str[100];

    printf("Grammar:  S -> 0A1\n");
    printf("          A -> 0A | 1A | epsilon\n\n");
    printf("Enter a string: ");
    scanf("%99s", str);

    if (belongs(str)) {
        printf("\nString \"%s\" BELONGS to the grammar\n", str);
        print_derivation(str);
    } else {
        printf("\nString \"%s\" does NOT belong to the grammar\n", str);
    }

    return 0;
}
